var openTabs = []; // 已打开的页签列表 [{ pageId, name, active }]

/**
 * 页签状态持久化（sessionStorage）
 * - 跳转进入（navigate）→ 恢复页签
 * - 手动刷新（reload）→ 清空重置
 */
function loadTabsFromStorage() {
    try {
        var stored = sessionStorage.getItem('openTabs');
        if (stored) {
            openTabs = JSON.parse(stored);
        }
    } catch (e) {
        console.warn('读取页签状态失败:', e);
        openTabs = [];
    }
}

function saveTabsToStorage() {
    try {
        sessionStorage.setItem('openTabs', JSON.stringify(openTabs));
    } catch (e) {
        console.warn('保存页签状态失败:', e);
    }
}

/**
 * 判断本次页面加载的导航类型
 * @returns {string} 'navigate' 跳转 | 'reload' 刷新 | 'back_forward' 前进后退
 */
function getNavigationType() {
    try {
        var entries = performance.getEntriesByType('navigation');
        if (entries && entries.length > 0) {
            return entries[0].type;
        }
    } catch (e) {}
    return 'navigate';
}

