// ===== 4. 渲染函数 =====

/**
 * 生成顶部导航 HTML（Logo + 菜单项 + 右侧功能区）
 */
function renderHeader() {
    var menuHtml = menuItems.map(function(item) {
        var cls = item.key === currentModule ? 'nav-menu-item active' : 'nav-menu-item';
        return '<a href="javascript:void(0)" class="' + cls + '" data-module="' + item.key + '" onclick="switchModule(\'' + item.key + '\')">' + item.name + '</a>';
    }).join('');

    return '' +
    '<header class="top-nav">' +
        '<div class="top-nav-left">' +
            '<div class="top-nav-brand">' + LOGO_SVG + '</div>' +
            '<nav class="top-nav-menu">' + menuHtml + '</nav>' +
        '</div>' +
        '<div class="top-nav-right">' +
            '<span class="org-selector">当前组织 ▾</span>' +
        '</div>' +
    '</header>';
}

/**
 * 生成侧边栏 HTML
 * 自动展开包含 activePage 的菜单组
 * 菜单项点击调用 switchPage(pageId)
 * 图标使用 SVG <use> 引用
 */
function renderSidebar(activePage) {
    var menus = sidebarConfig[currentModule] || [];
    var html = '<ul class="sidebar-menu">';

    menus.forEach(function(group, groupIdx) {
        // 检查该菜单组是否包含当前激活页面
        var isExpanded = false;
        var hasActive = false;
        group.children.forEach(function(child) {
            if (child.pageId === activePage) {
                isExpanded = true;
                hasActive = true;
            }
        });
        // 默认展开第一个菜单组
        if (groupIdx === 0 && !hasActive) isExpanded = true;

        // 2级菜单：expanded（展开）+ has-active（子项被选中）
        var itemClass = 'sidebar-menu-item';
        if (isExpanded) itemClass += ' expanded';
        if (hasActive) itemClass += ' has-active';

        html += '<li>';
        html += '<a href="javascript:void(0)" class="' + itemClass + '" onclick="toggleSubmenu(this)">';
        html += '<svg class="sidebar-menu-icon"><use href="#' + group.icon + '"></use></svg>';
        html += '<span>' + group.name + '</span>';
        html += '<svg class="sidebar-menu-expand"><use href="#icon-chevron-down"></use></svg>';
        html += '</a>';
        html += '<ul class="submenu">';

        group.children.forEach(function(child) {
            var childClass = child.pageId === activePage ? 'submenu-item active' : 'submenu-item';
            html += '<li><a href="javascript:void(0)" class="' + childClass + '" data-page-id="' + child.pageId + '" onclick="switchPage(\'' + child.pageId + '\')">' + child.name + '</a></li>';
        });

        html += '</ul></li>';
    });

    html += '</ul>';
    return html;
}

// ===== 5. 核心逻辑 =====

/**
 * 获取模块的默认页面 ID
 */
function getDefaultPage(moduleKey) {
    var menus = sidebarConfig[moduleKey] || [];
    for (var i = 0; i < menus.length; i++) {
        for (var j = 0; j < menus[i].children.length; j++) {
            if (menus[i].children[j].isDefault) return menus[i].children[j].pageId;
        }
    }
    // 没有标记 isDefault，返回第一个页面
    if (menus.length > 0 && menus[0].children.length > 0) {
        return menus[0].children[0].pageId;
    }
    return null;
}

/**
 * ⭐核心：模块切换
 * - 更新 currentModule
 * - 仅更新顶部导航 active 高亮（不重建 DOM，避免闪烁和事件丢失）
 * - 重新渲染侧边栏
 * - 加载默认页面
 */
function switchModule(moduleKey) {
    if (moduleKey === currentModule) return;
    currentModule = moduleKey;
    // 持久化模块选择，MPA 跳转后新页面 initShell 从 sessionStorage 恢复，保持顶部菜单切换状态
    try { sessionStorage.setItem('currentModule', currentModule); } catch (e) {}
    currentPage = getDefaultPage(moduleKey);

    // 仅更新顶部导航 active 高亮（不重建 DOM）
    document.querySelectorAll('.nav-menu-item').forEach(function(item) {
        if (item.getAttribute('data-module') === moduleKey) {
            item.classList.add('active');
        } else {
            item.classList.remove('active');
        }
    });

    // 重新渲染侧边栏
    var sidebarEl = document.getElementById('sidebar');
    if (sidebarEl) {
        sidebarEl.innerHTML = renderSidebar(currentPage);
    }

    // 加载默认页面
    if (currentPage) {
        switchPage(currentPage);
    }
}

/**
 * 初始化导航壳
 * - 注入 SVG Sprite 到 body
 * - 确定默认模块和默认页面
 * - 渲染顶部导航
 * - 渲染侧边栏
 */
function initShell() {
    // 注入 SVG Sprite 到 body 开头
    var spriteContainer = document.createElement('div');
    spriteContainer.innerHTML = SVG_SPRITE;
    if (spriteContainer.firstChild) {
        document.body.insertBefore(spriteContainer.firstChild, document.body.firstChild);
    }

    // 确定默认模块
    // 优先从 sessionStorage 恢复模块（MPA 跳转后保持顶部菜单切换状态）
    var storedModule = null;
    try { storedModule = sessionStorage.getItem('currentModule'); } catch (e) {}
    var defaultModule = menuItems.find(function(m) { return m.key === storedModule; });
    if (!defaultModule) defaultModule = menuItems.find(function(m) { return m.isDefault; });
    if (!defaultModule) defaultModule = menuItems[0];
    currentModule = defaultModule.key;

    // 查找当前页面：URL 参数 pageId 优先（支持同一 HTML 模板服务多个 pageId，如 form.html 同时服务 user-form/sys-config），其次 __pageId，最后默认页
    var __urlPageId = (location.search.match(/pageId=([^&]+)/) || [])[1];
    if (__urlPageId) {
        currentPage = decodeURIComponent(__urlPageId);
    } else if (window.__pageId) {
        currentPage = window.__pageId;
    } else {
        currentPage = getDefaultPage(currentModule);
    }

    // 渲染顶部导航
    var headerEl = document.getElementById('header');
    if (headerEl) {
        headerEl.innerHTML = renderHeader();
    }

    // 渲染侧边栏
    var sidebarEl = document.getElementById('sidebar');
    if (sidebarEl) {
        sidebarEl.innerHTML = renderSidebar(currentPage);
    }
}

/**
 * ⭐核心：页面切换（MPA 真实跳转）
 * - 点击菜单 → 跳转到目标 HTML 页面
 * - 侧边栏高亮由目标页面加载时 initShell() 自动渲染，无需手动处理
 */
function switchPage(pageId, module) {
    // ⭐ 点击的就是当前页面 → 不跳转，避免页面无意义 reload
    if (pageId === currentPage) {
        // 仅处理模块切换（跨模块页签复用同一 pageId 的场景）
        if (module && module !== currentModule) {
            currentModule = module;
            try { sessionStorage.setItem('currentModule', currentModule); } catch (e) {}
            window.location.reload();
        }
        return;
    }
    // 可选 module 参数：跨模块切换页签时，先更新 currentModule 并持久化（新页面 initShell 从 sessionStorage 恢复）
    if (module && module !== currentModule) {
        currentModule = module;
        try { sessionStorage.setItem('currentModule', currentModule); } catch (e) {}
    }
    var route = pageRoute[pageId];
    if (!route) {
        console.warn('未找到页面路由:', pageId);
        return;
    }

    // 当前页面位于 pages/ 目录时，跳转路径需要加上 ../ 前缀
    var inPagesDir = window.location.pathname.indexOf('/pages/') !== -1;
    window.location.href = (inPagesDir ? '../' : '') + route.file + '?pageId=' + encodeURIComponent(pageId);
}

/**
 * 侧边栏展开/收起
 */
function toggleSubmenu(element) {
    // 子菜单显隐由 CSS 状态类驱动：.sidebar-menu-item.expanded .submenu
    // （与箭头旋转 .expanded .sidebar-menu-expand 同构，结构样式分离）
    element.classList.toggle('expanded');
}

// ===== 5.5 系统级页签管理 =====

/**
 * 添加/激活页签
 * - 页面已打开过 → 仅切换激活状态
 * - 页面未打开过 → 添加新页签并激活
 * @param {string} pageId - 页面ID
 */
function addTab(pageId) {
    var route = pageRoute[pageId];
    if (!route) return;

    // 从 sidebarConfig 查当前模块下该 pageId 的菜单名称（pageId 复用时按模块区分显示）
    var tabName = route.name;
    var menus = sidebarConfig[currentModule] || [];
    for (var mi = 0; mi < menus.length; mi++) {
        for (var ci = 0; ci < menus[mi].children.length; ci++) {
            if (menus[mi].children[ci].pageId === pageId) {
                tabName = menus[mi].children[ci].name;
                break;
            }
        }
    }

    // 查找是否已存在该页签（按 module + pageId 去重，支持不同模块复用同一 pageId）
    var existing = null;
    for (var i = 0; i < openTabs.length; i++) {
        if (openTabs[i].module === currentModule && openTabs[i].pageId === pageId) {
            existing = openTabs[i];
            break;
        }
    }

    if (existing) {
        // 已存在：取消所有激活，激活当前
        openTabs.forEach(function(tab) { tab.active = false; });
        existing.active = true;
        // ⭐ 同步更新名称为当前模块下该 pageId 的最新菜单名称
        // 避免 pageId 跨模块复用时页签名称未刷新（如 system 的"用户列表"切换后应显示 lowcode 的"应用列表"）
        existing.name = tabName;
    } else {
        // 不存在：取消所有激活，添加新页签
        openTabs.forEach(function(tab) { tab.active = false; });
        openTabs.push({ module: currentModule, pageId: pageId, name: tabName, active: true });
    }
    renderTabs();
    saveTabsToStorage();
}

/**
 * 关闭页签
 * - 关闭非激活页签 → 仅移除页签，不切换页面
 * - 关闭激活页签 → 移除页签 + 切换到相邻页签
 * - 关闭最后一个页签 → 清空页面内容
 * @param {string} pageId - 页面ID
 * @param {Event} event - 事件对象（阻止冒泡）
 */
function closeTab(module, pageId, event) {
    if (event) event.stopPropagation();

    // 查找页签索引（按 module + pageId 定位，避免不同模块复用 pageId 时删错）
    var tabIndex = -1;
    for (var i = 0; i < openTabs.length; i++) {
        if (openTabs[i].module === module && openTabs[i].pageId === pageId) {
            tabIndex = i;
            break;
        }
    }
    if (tabIndex === -1) return;

    var wasActive = openTabs[tabIndex].active;
    openTabs.splice(tabIndex, 1);
    // ⭐ 立即同步移除的页签到 sessionStorage，避免 switchPage 跳转后目标页 loadTabsFromStorage 把已关闭的页签恢复回来
    saveTabsToStorage();

    if (wasActive && openTabs.length > 0) {
        // 关闭的是当前激活页签 → 切换到相邻页签（带 module，确保跳转到正确模块）
        var newTabIndex = Math.min(tabIndex, openTabs.length - 1);
        var newTab = openTabs[newTabIndex];
        switchPage(newTab.pageId, newTab.module); // switchPage 内部会调用 addTab 更新激活状态
    } else {
        // 关闭的不是当前激活页签，或没有页签了
        renderTabs();
        if (openTabs.length === 0) {
            // 最后一个页签被关闭，清空页面内容
            var content = document.getElementById('page-content');
            if (content) content.innerHTML = '';
            var mainContent = document.querySelector('.main-content');
            if (mainContent) mainContent.classList.remove('has-tabs');
        }
    }
}

/**
 * 渲染页签
 * - 0个页签 → 隐藏容器，移除 has-tabs 类
 * - 1个页签 → 显示容器，不显示关闭图标
 * - ≥2个页签 → 显示容器，显示关闭图标
 */
function renderTabs() {
    var container = document.getElementById('tabs-nav-container');
    if (!container) return;

    var mainContent = document.querySelector('.main-content');

    if (openTabs.length === 0) {
        container.innerHTML = '';
        container.style.display = 'none';
        if (mainContent) mainContent.classList.remove('has-tabs');
        return;
    }

    container.style.display = 'block';
    if (mainContent) mainContent.classList.add('has-tabs');

    // ⭐ 只有1个页签时不显示关闭图标，≥2个时显示
    var showClose = openTabs.length >= 2;

    var html = '<div class="tabs-nav">';
    openTabs.forEach(function(tab) {
        var itemClass = tab.active ? 'nav-item is-active' : 'nav-item';
        html += '<div class="' + itemClass + '" data-page-id="' + tab.pageId + '" data-module="' + tab.module + '" onclick="switchPage(\'' + tab.pageId + '\', \'' + tab.module + '\')">';
        html += '<span>' + tab.name + '</span>';
        if (showClose) {
            html += '<span class="close-icon" onclick="closeTab(\'' + tab.module + '\', \'' + tab.pageId + '\', event)">';
            html += '<svg class="icon icon-sm"><use href="#icon-remove"></use></svg>';
            html += '</span>';
        }
        html += '</div>';
    });
    html += '</div>';

    container.innerHTML = html;

    // ⭐ 自动滚动到激活页签（超出容器时）
    var activeItem = container.querySelector('.nav-item.is-active');
    if (activeItem) {
        // scrollIntoView 会将激活页签滚动到可见区域
        // inline: 'nearest' 避免不必要的滚动，behavior: 'smooth' 平滑滚动
        activeItem.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
    }
}

// ===== 6. 自动执行 =====
// MPA 模式：初始化导航壳后，根据导航类型恢复或重置页签
// - navigate（跳转进入/首次打开/前进后退）：从 sessionStorage 恢复已打开页签，再激活当前页 → 页签记录跨页面保留
// - reload（手动刷新）：清空 sessionStorage，仅保留当前页一个页签
// 各页面通过 <script>window.__pageId='xxx'</script> 声明自己的页面 ID
initShell();

var navType = getNavigationType();
if (navType === 'reload') {
    // 手动刷新：清空页签记录，仅保留当前页
    openTabs = [];
    try { sessionStorage.removeItem('openTabs'); } catch (e) {}
    addTab(currentPage);
} else {
    // 跳转进入/首次打开/前进后退：先恢复已打开页签，再激活当前页（addTab 内部会去重并更新激活态）
    loadTabsFromStorage();
    addTab(currentPage);
}

if (window.__skipSwitch) {
    // preview 模式：覆盖 switchPage，阻止菜单点击切换页面
    window.switchPage = function() {};
}

// ===== 7. 响应式缩放适配（原型预览专用）=====
/**
 * 原型预览自适应缩放
 * 基准画布 1280px，放大上限 120%（1.2倍）
 * - 屏幕宽度 ≤ 1280：不放大
 * - 1280 < 屏幕宽度 < 1536：等比放大
 * - 屏幕宽度 ≥ 1536：封顶 1.2，流式布局撑满
 * ⚠️ 仅作用于 body 的 zoom 属性，不修改任何设计 token 或页面原始数值
 */
var PREVIEW_BASE_WIDTH = 1280;
var PREVIEW_MAX_SCALE = 1.2;
// 首次启动标记：用于区分「页面加载/跳转后第一次执行」与「窗口 resize」
// - 首次：禁用 zoom 过渡，避免整页从 zoom:1 放大到 scale 的过渡动画（实现无感切换）
// - resize：保留过渡，窗口尺寸变化时仍平滑缩放
var __zoomBooted = false;

function applyResponsiveZoom() {
    var screenWidth = window.innerWidth;
    var scale;
    // 基准宽度 +20px 容差，吸收窗口边框/DPI/滚动条导致的 innerWidth 偏差
    // 避免视觉上=1280 时因 innerWidth 略大（如1337）而误触发放大
    if (screenWidth <= PREVIEW_BASE_WIDTH + 20) {
        scale = 1;
    } else if (screenWidth < PREVIEW_BASE_WIDTH * PREVIEW_MAX_SCALE) {
        scale = screenWidth / PREVIEW_BASE_WIDTH;
    } else {
        scale = PREVIEW_MAX_SCALE;
    }

    var body = document.body;
    if (!body) return;

    // ⭐ 首次启动：临时关闭 zoom 过渡，让首屏直接以目标 scale 渲染，消除切换页面时的放大动画
    if (!__zoomBooted) {
        body.style.transition = 'none';
    }
    body.style.zoom = scale;
    // 设置 --zoom-value 变量，供全屏组件（抽屉/弹窗）用 calc(100vw / var(--zoom-value)) 抵消 zoom 放大
    document.documentElement.style.setProperty('--zoom-value', scale);
    if (!__zoomBooted) {
        // 强制 reflow，确保上面的 transition:none + zoom 立即生效（不被浏览器合并到下一帧）
        void body.offsetHeight;
        // 恢复 CSS 默认过渡（common.css 的 transition: zoom 0.15s ease），后续 resize 仍平滑
        body.style.transition = '';
        __zoomBooted = true;
    }
}

applyResponsiveZoom();
window.addEventListener('resize', applyResponsiveZoom);

// ===== 8. 切页优化：目标页预载（Speculation Rules，渐进增强） =====
// hover/按下菜单即预取目标 HTML，MPA 跳转的文档加载间隙显著缩短，白屏近乎消失；
// 配合 common.css 顶部 @view-transition（新旧文档 crossfade），近 SPA 观感。
// Chrome/Edge 121+ 生效；不支持的浏览器创建 script 会被忽略，静默降级为零开销。
(function prefetchPagesOnHover() {
    try {
        var inPagesDir = window.location.pathname.indexOf('/pages/') !== -1;
        var seen = {};
        var urls = [];
        Object.keys(pageRoute).forEach(function (k) {
            // 复用 switchPage 的路径规则：pages/ 下页面跳根目录需 ../ 前缀
            var abs = new URL((inPagesDir ? '../' : '') + pageRoute[k].file, window.location.href).href;
            if (!seen[abs]) { seen[abs] = 1; urls.push(abs); }
        });
        if (!urls.length) return;
        var el = document.createElement('script');
        el.type = 'speculationrules';
        el.textContent = JSON.stringify({ prefetch: [{ urls: urls, eagerness: 'moderate' }] });
        document.head.appendChild(el);
    } catch (e) { /* 静默降级：老浏览器无此 API 时零影响 */ }
})();
